"use strict";

var fs = require("fs");
var path = require("path");

var repositoryRoot = path.resolve(__dirname, "..");
var environment = process.argv[2] || "development";

if (environment !== "development" && environment !== "production") {
    process.stderr.write("Unknown build environment: " + environment + "\n");
    process.exit(1);
}

var isDevelopment = environment === "development";
var output = [
    "// Generated by scripts/generate-build-config.js. Do not edit manually.",
    "class BuildConfig {",
    "    public static environment: string = \"" + environment + "\";",
    "    public static cb3CandyFacadeEnabled: boolean = false;",
    "    public static cb3ForgePurchaseEnabled: boolean = false;",
    "    public static cb3DomainEventsEnabled: boolean = false;",
    "    public static cb3ContentValidationStrict: boolean = false;",
    "    public static cb3DiagnosticsEnabled: boolean = false;",
    "",
    "    public static isDevelopment(): boolean {",
    "        return " + (isDevelopment ? "true" : "false") + ";",
    "    }",
    "",
    "    public static applyEnvironmentUi(): void {",
    "        var devModeButton: HTMLElement = document.getElementById(\"dev-mode-btn\");",
    "        if (devModeButton) {",
    "            devModeButton.style.display = BuildConfig.isDevelopment() ? \"\" : \"none\";",
    "        }",
    "    }",
    "}",
    ""
].join("\n");

var outputPath = path.join(repositoryRoot, "code", "gen", "BuildConfig.ts");
fs.mkdirSync(path.dirname(outputPath), { recursive: true });
fs.writeFileSync(outputPath, output, "utf8");
process.stdout.write("Generated " + outputPath + " for " + environment + ".\n");
